//   Course Clips/ 8 - Storyline Stars/ 8 - Tutorials/ FiRsT Tutoria/8-E1-1-2 Color Back GFX / layer 'Layer 3' / frame 1
void frame_6274_0(Activation& scope) {
    if (strictNotEquals(_root["TotalStars"], 0)) {
        scope["color"] = Math["round"](_root["TotalStars"] * 1.5) + 25;
        scope["color2"] = Math["abs"](100 - scope["color"]);
        scope["myColor"] = new_(Color, scope.self);
        scope["colorTrans"] = new_(Object);
        scope["colorTrans"] = obj({{"ra", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"rb", 0}, {"ga", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"gb", 0}, {"ba", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"bb", 0}, {"aa", 100}, {"ab", 0}});
        scope["myColor"]["setTransform"](scope["colorTrans"]);
        scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
            scope["color"] += Math["round"](((_root["TotalStars"] * 1.5) + 25) - scope["color"]) / 7;
            if (_root["CheatCastleRestore"] == true) {
                scope["color"] = 100;
            }
            //color = Math.max(color, 0);
            //color = Math.min(color, 100);
            if (scope["color"] > 100) {
                scope["oldcolor"] = scope["color"];
                scope["color"] += Math["abs"](100 - scope["color"]) * 2.5;
            }
            scope["color2"] = Math["abs"](100 - scope["color"]);
            // color = percent of stars obained
            // color 2  = percent of stars not yet obtained
            scope["colorTrans"] = obj({{"ra", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"rb", 0}, {"ga", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"gb", 0}, {"ba", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"bb", 0}, {"aa", 100}, {"ab", 0}});
            scope["myColor"]["setTransform"](scope["colorTrans"]);
            if (scope["color"] > 100) {
                scope["color"] = scope["oldcolor"];
            }
            return undefined;
        });
    }
}

