//   Course Clips/ 8 - Storyline Stars/9-03-2 Floating Cannon / layer 'Layer 5' / frame 1
void frame_6807_0(Activation& scope) {
    scope["HitTest"] = scope.function([](Activation& scope) -> Value {
        Value ground = scope.args[0];
        Value X = scope.args[1];
        Value Y = scope.args[2];
        if (_root["Course"][ground]["hitTest"](((X) * _root["coursescale"] / 100) + (scope["_parent"]["_x"] * _root["coursescale"] / 100) + _root["Course"]["_x"], ((Y) * _root["coursescale"] / 100) + (scope["_parent"]["_y"] * _root["coursescale"] / 100) + _root["Course"]["_y"], true) || _root["Course"]["BPlatforms"]["hitTest"](((scope["_x"]) * _root["coursescale"] / 100) + (scope["_parent"]["_x"] * _root["coursescale"] / 100) + _root["Course"]["_x"], ((scope["_y"]) * _root["coursescale"] / 100) + (scope["_parent"]["_y"] * _root["coursescale"] / 100) + _root["Course"]["_y"], true)) {
            return (true);
        } else {
            return (false);
        }
        return undefined;
    });
    scope["yspeed"] = 0;
    scope["maxY"] = scope["_y"];
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        scope["yspeed"] *= 0.7;
        if (scope["HitTest"]("Water", scope["_x"], scope["_y"])) {
            scope["count"] = 0;
            for (scope["i"] = 0; scope["i"] < 7; scope["i"]++) {
                if (scope["HitTest"]("Water", scope["_x"], scope["_y"] - scope["i"] * 2)) {
                    scope["count"]++;
                }
            }
            scope["yspeed"] -= scope["count"] / 10;
        } else {
            scope["yspeed"] += 1;
        }
        scope["_y"] += scope["yspeed"];
        scope["_y"] = Math["min"](scope["_y"], scope["maxY"]);
        _root["Course"]["BackGFX"]["cannon2"]["_y"] = scope["_y"];
        _root["Course"]["Platforms"]["cannon"]["_y"] = scope["_y"];
        return undefined;
    });
}

